// a command of vynst: msg.payload.command = open | lock
// replace this node by your relay; send the result to "inwendo erp lock result" (msg.success, msg.state)
const id = "front_door";
const relockMs = 5000;
const locks = flow.get('locks') || {};
const lock = locks[id];
const command = msg.payload.command;
const event = { at: Date.now(), source: 'erp', command, command_id: msg.payload.command_id, smart_lock_id: msg.payload.smart_lock_id };
if (lock.jammed) {
  event.result = 'jammed';
  lock.events.push(event);
  flow.set('locks', locks);
  msg.success = false;
  msg.state = 'jammed';
  msg.message = 'bolt jammed';
  return [msg, null];
}
lock.state = command === 'open' ? 'unlocked' : 'locked';
event.result = lock.state;
lock.events.push(event);
flow.set('locks', locks);
msg.success = true;
msg.state = lock.state;
if (command === 'open' && relockMs > 0) {
  setTimeout(() => {
    const all = flow.get('locks');
    all[id].state = 'locked';
    all[id].events.push({ at: Date.now(), source: 'relock', result: 'locked' });
    flow.set('locks', all);
    // the lock node reports the new state to vynst
    node.send([null, { payload: 'locked' }]);
  }, relockMs);
}
return [msg, null];

