// from the http endpoint (POST /virtual-locks/:lock/reader {"credential": "..."}) or from the inject node
const bridges = {"front_door":"mqtt","gym":"mqtt"};
const order = ["mqtt"];
const out = new Array(order.length + 1).fill(null);
if (msg.req) {
  msg.lockId = msg.req.params.lock;
  if (msg.req.body && msg.req.body.credential_type) msg.credentialType = msg.req.body.credential_type;
  msg.payload = msg.payload && msg.payload.credential;
}
if (!bridges[msg.lockId]) {
  msg.statusCode = 404;
  msg.payload = { error: 'unknown lock ' + msg.lockId };
  out[order.length] = msg;
  return out;
}
out[order.indexOf(bridges[msg.lockId])] = msg;
return out;

const locks = flow.get('locks') || {};
const lock = locks[msg.lockId];
const event = { at: Date.now(), source: 'reader', person: msg.person || null, result: 'jammed' };
if (!lock.jammed) {
  lock.state = 'unlocked';
  event.result = 'unlocked';
}
lock.events.push(event);
flow.set('locks', locks);
msg.payload = { ...msg.payload, door_opened: !lock.jammed };
const relock = {"front_door":5000,"gym":5000}[msg.lockId];
if (!lock.jammed && relock > 0) {
  const id = msg.lockId;
  setTimeout(() => {
    const all = flow.get('locks');
    all[id].state = 'locked';
    all[id].events.push({ at: Date.now(), source: 'relock', result: 'locked' });
    flow.set('locks', all);
  }, relock);
}
return msg;

