const locks = flow.get('locks') || {};
const lock = locks[msg.req.params.lock];
if (!lock) {
  msg.statusCode = 404;
  msg.payload = {};
  return msg;
}
lock.jammed = msg.payload.jammed === true;
flow.set('locks', locks);
msg.payload = lock;
return msg;
